type AcademicSection = "Nursery" | "Primary" | "Junior" | "Senior";
const sectionMatchesClass = (section: AcademicSection | "", databaseSection: string) => {
  if (!section) return true;
  const value = databaseSection.trim().toLowerCase();
  if (section === "Nursery") return value.includes("nursery");
  if (section === "Primary") return value.includes("primary");
  if (section === "Junior") return value.includes("jss") || value.includes("junior");
  return value.includes("sss") || value.includes("senior");
};

const downloadWorkbook = (fileName: string, sheetName: string, rows: Array<Record<string, unknown>>) => { const worksheet = XLSX.utils.json_to_sheet(rows); const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, worksheet, sheetName); XLSX.writeFile(workbook, fileName); };

