const escapeReceiptHtml = (value: unknown) => String(value ?? "").replace(/[&<>\"']/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" }[character] ?? character));
const openPaymentReceipt = (payment: { reference: string; receiptNumber?: string | null; amountKobo: number; method: string; studentName?: string | null; admissionNo?: string | null; createdAt?: Date | string | null; receiptIssuedAt?: Date | string | null }, settings = defaultReceiptSettings) => { const popup = window.open("", "_blank", "width=720,height=820"); if (!popup) return; const schoolName = escapeReceiptHtml(settings.schoolName); const schoolAddress = escapeReceiptHtml(settings.schoolAddress); const schoolPhone = escapeReceiptHtml(settings.schoolPhone); const receiptHeader = escapeReceiptHtml(settings.receiptHeader); const receiptFooter = escapeReceiptHtml(settings.receiptFooter); const receiptNumber = escapeReceiptHtml(payment.receiptNumber ?? "Not yet assigned"); const reference = escapeReceiptHtml(payment.reference); const studentName = escapeReceiptHtml(payment.studentName ?? "Student"); const admissionNo = escapeReceiptHtml(payment.admissionNo ?? "—"); const method = escapeReceiptHtml(payment.method.replace("_", " ")); const issuedAt = new Date(payment.receiptIssuedAt ?? payment.createdAt ?? Date.now()).toLocaleString(); popup.document.write(`<html><head><title>${schoolName} payment receipt ${receiptNumber}</title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;padding:32px;color:#17203a;background:#f8f9fc}main{border:1px solid #dce1ed;padding:32px;max-width:620px;margin:0 auto;background:#fff}header{border-bottom:3px solid #4f46e5;padding-bottom:18px;margin-bottom:18px}h1{color:#202a70;margin:0 0 6px;font-size:25px}header p{margin:4px 0;color:#586174}table{border-collapse:collapse;width:100%;margin:18px 0}td{padding:12px 4px;border-bottom:1px solid #edf0f5}td:first-child{font-weight:700;width:38%}.paid{color:#15803d;font-weight:700}.receipt-number{font-size:18px;color:#312e81;font-weight:700}</style></head><body><main><header><h1>${schoolName}</h1><p>${schoolAddress}</p>${schoolPhone ? `<p>${schoolPhone}</p>` : ""}<p>${receiptHeader}</p></header><p class="receipt-number">Receipt number: ${receiptNumber}</p><table><tr><td>Student</td><td>${studentName}</td></tr><tr><td>Admission number</td><td>${admissionNo}</td></tr><tr><td>Reference</td><td>${reference}</td></tr><tr><td>Amount</td><td>₦${(payment.amountKobo / 100).toLocaleString()}</td></tr><tr><td>Method</td><td>${method}</td></tr><tr><td>Status</td><td class="paid">VERIFIED</td></tr><tr><td>Issued</td><td>${escapeReceiptHtml(issuedAt)}</td></tr></table><p>${receiptFooter}</p><button onclick="window.print()">Print receipt</button></main></body></html>`); popup.document.close(); };

