function StatCard({ label, value, change, icon: Icon, tone, down }: { label: string; value: string; change: string; icon: typeof Users; tone: string; down?: boolean }) {
  return (
    <div className="stat-card group">
      <div className="flex items-start justify-between gap-3">
        <div className={`icon-tile ${tone}`}><Icon size={18} strokeWidth={2.2} /></div>
        <button className="ghost-icon opacity-0 transition-opacity group-hover:opacity-100" onClick={() => toast.info(`${label} details are coming soon`)} aria-label={`View ${label} details`}><MoreHorizontal size={17} /></button>
      </div>
      <div className="mt-5 flex items-end justify-between gap-4">
        <div><p className="eyebrow">{label}</p><p className="stat-value">{value}</p></div>
        <span className={`change-pill ${down ? "negative" : "positive"}`}>{down ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{change}</span>
      </div>
      <div className="mt-4 h-1 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${tone}`} style={{ width: down ? "54%" : "78%" }} /></div>
    </div>
  );
}

function getNurserySubjectScore(scores: Array<{ subject: string; firstCa: number; secondCa: number; thirdCa: number; examScore: number }> | undefined, subjectName: string) { return scores?.find(score => score.subject === subjectName); }
function getNurserySubjectTotal(scores: Array<{ subject: string; firstCa: number; secondCa: number; thirdCa: number; examScore: number }> | undefined, subjectName: string) { const score = getNurserySubjectScore(scores, subjectName); return score ? score.firstCa + score.secondCa + score.thirdCa + score.examScore : null; }
function getNurserySubjectGrade(total: number | null) { return total === null ? "" : total >= 80 ? "A" : total >= 65 ? "B" : total >= 50 ? "C" : total >= 40 ? "D" : "E"; }
function SectionHeading({ title, subtitle, action }: { title: string; subtitle?: string; action?: string }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div><h2 className="section-title">{title}</h2>{subtitle && <p className="muted mt-1">{subtitle}</p>}</div>{action && <button className="text-action" onClick={() => toast.info(`${action} view is coming soon`)}>{action}<ArrowUpRight size={14} /></button>}</div>;
}

type AcademyAnnouncement = { id: number; title: string; summary: string; publishedAt: Date | string };

function NotificationCenter({ announcements }: { announcements: AcademyAnnouncement[] }) {
  const [open, setOpen] = useState(false);
  const [filter, setFilter] = useState<"all" | "unread" | "read">("all");
  const [readIds, setReadIds] = useState<number[]>(() => {
    if (typeof window === "undefined") return [];
    try { return JSON.parse(window.localStorage.getItem("alfurqan-read-notifications") ?? "[]") as number[]; } catch { return []; }
  });
  useEffect(() => { window.localStorage.setItem("alfurqan-read-notifications", JSON.stringify(readIds)); }, [readIds]);
  const unread = announcements.filter(item => !readIds.includes(item.id));
  const visibleAnnouncements = announcements.slice(0, 8).filter(item => filter === "all" || (filter === "unread" ? !readIds.includes(item.id) : readIds.includes(item.id)));
  const markRead = (id: number) => setReadIds(current => current.includes(id) ? current : [...current, id]);
  const markAllRead = () => setReadIds(current => Array.from(new Set([...current, ...announcements.map(item => item.id)])));
  return <div className="notification-wrap">
    <button className="icon-button notification-button" onClick={() => setOpen(current => !current)} aria-label={`Notifications${unread.length ? `, ${unread.length} unread` : ""}`} aria-expanded={open}><Bell size={18} />{unread.length > 0 && <span aria-hidden="true" />}</button>
    {open && <div className="notification-panel" role="dialog" aria-label="School notification center">
      <div className="notification-panel-head"><div><b>Notification center</b><small>{unread.length ? `${unread.length} unread school update${unread.length === 1 ? "" : "s"}` : "You are all caught up"}</small></div><button onClick={markAllRead} disabled={!unread.length}>Mark all read</button></div>
      <div className="notification-filters" role="group" aria-label="Filter school notifications">{(["all", "unread", "read"] as const).map(option => <button key={option} type="button" className={filter === option ? "active" : ""} onClick={() => setFilter(option)}>{option === "all" ? "All" : option === "unread" ? `Unread (${unread.length})` : "Read"}</button>)}</div>
      {visibleAnnouncements.length ? visibleAnnouncements.map(item => <button className={`notification-item ${!readIds.includes(item.id) ? "unread" : ""}`} key={item.id} onClick={() => markRead(item.id)}><span className="notification-bullet" /><span><b>{item.title}</b><small>{item.summary}</small><time>{new Date(item.publishedAt).toLocaleString()}</time></span></button>) : <div className="notification-empty"><Bell size={18} /><span>{announcements.length ? filter === "unread" ? "No unread school alerts." : "No read school alerts yet." : "No published school alerts yet."}</span></div>}
      <div className="notification-panel-foot">Updates published by Al-furqan Science Academy Lafia appear here. Browser push remains opt-in and disabled until the school policy is approved.</div>
    </div>}
  </div>;
}

function PwaInstallControl({ snapshot, showFallback = false }: { snapshot: ReturnType<typeof getPwaSnapshot>; showFallback?: boolean }) {
  if (snapshot.installed) return <span className="pwa-installed-status" title="This portal is installed on this device"><CheckCircle2 size={14} /> Installed</span>;
  if (!snapshot.supported && !showFallback) return null;
  if (!snapshot.installAvailable && !showFallback) return null;
  const handleInstall = async () => {
    const accepted = await promptPwaInstall();
    if (!accepted) toast.info("If the install prompt does not appear, open your browser menu and choose Add to Home screen or Install app.");
  };
  return <button className="install-app-button" onClick={() => void handleInstall()} title="Install Al-furqan School Portal"><DownloadCloud size={15} /> Install app</button>;
}

function PwaUpdateControl({ snapshot }: { snapshot: ReturnType<typeof getPwaSnapshot> }) {
  if (!snapshot.updateAvailable) return null;
  return <button className="pwa-update-button" onClick={applyPwaUpdate} title="Apply the latest portal update"><RefreshCw size={14} /> Update available</button>;
}

